const layers={
  water:{label:'AGUA / LO QUE SOSTIENE LA VIDA',title:'Cada gota tiene una historia.',text:'Explora cómo la humedad y los días sin riego cambian el escenario de tu cultivo.',tag:'Explora el simulador',symbol:'≈'},
  climate:{label:'CLIMA / LAS SEÑALES DEL ENTORNO',title:'Lee las señales del cielo.',text:'Consulta el histórico climático de 2025 y conoce los límites de la predicción experimental.',tag:'Conoce el clima',symbol:'☀'},
  soil:{label:'SUELO / LA MEMORIA DE TU TIERRA',title:'Lo que no ves también importa.',text:'Reúne los registros de tu suelo y crea una Semilla NORTEX que represente tu escenario.',tag:'Descubre tu semilla',symbol:'◈'}
};
const tree=(x,y,i)=>`<g transform="translate(${x} ${y})" class="home-tree" style="--tree-delay:${i%4*-.7}s"><ellipse cy="10" rx="23" ry="9" fill="#123d3040"/><path d="M0 8V-30" stroke="#695139" stroke-width="7"/><path d="M0-9l-12-17M1-14l12-19" stroke="#695139" stroke-width="4"/><circle cy="-37" r="25" fill="#286445"/><circle cx="-14" cy="-35" r="17" fill="#427e4b"/><circle cx="8" cy="-48" r="19" fill="#77a550"/><circle cx="-2" cy="-43" r="13" fill="#9bb957"/><g fill="#ffc66d"><ellipse cx="-14" cy="-30" rx="4" ry="6" transform="rotate(-20 -14 -30)"/><ellipse cx="15" cy="-38" rx="4" ry="6"/><ellipse cx="1" cy="-21" rx="4" ry="6"/></g></g>`;
function landscape(){return `<svg viewBox="0 0 700 590" role="img" aria-label="Ilustración interactiva de una finca con mangos, parcelas y un canal de riego. No es un mapa real."><defs><linearGradient id="home-soil" x2="0" y2="1"><stop stop-color="#ab7d4b"/><stop offset="1" stop-color="#674b35"/></linearGradient><linearGradient id="home-canopy" x2="1" y2="1"><stop stop-color="#d5e7a1"/><stop offset="1" stop-color="#93b565"/></linearGradient><pattern id="home-crops" width="17" height="17" patternUnits="userSpaceOnUse" patternTransform="rotate(30)"><rect width="17" height="17" fill="#96b96a"/><path d="M4 0v17" stroke="#d3df8f" stroke-width="6"/></pattern></defs><ellipse class="home-shadow" cx="355" cy="493" rx="255" ry="35" fill="#021c1a" opacity=".4"/><g class="home-island"><path class="home-soil-edge" d="M68 307L351 147 635 306V359L352 519 68 360Z" fill="url(#home-soil)"/><path d="M352 467V519L635 359V306Z" fill="#715337"/><path d="M68 332L352 492 635 332M68 348L352 508 635 348" fill="none" stroke="#c2a16e" stroke-width="2" opacity=".45"/><path d="M68 307L351 147 635 306 352 467Z" fill="url(#home-canopy)" stroke="#d6e6a1" stroke-width="2"/><path d="M325 165L588 313 484 373 222 225Z" fill="#a2bf76"/><path d="M110 313L228 245 362 323 244 390Z" fill="url(#home-crops)" stroke="#eff3bd" stroke-width="2"/><path d="M268 403L387 336 503 403 383 470Z" fill="url(#home-crops)" stroke="#eff3bd" stroke-width="2"/><path class="home-stream-bed" d="M174 249Q280 293 333 304T448 356Q498 392 560 350" fill="none" stroke="#e5e7b5" stroke-width="22"/><path class="home-stream" d="M174 249Q280 293 333 304T448 356Q498 392 560 350" fill="none" stroke="#6ccdc1" stroke-width="12"/><path class="home-current" d="M174 249Q280 293 333 304T448 356Q498 392 560 350" fill="none" stroke="#d0fff2" stroke-width="2" stroke-dasharray="12 25"/>
${[[337,224],[396,255],[455,288],[292,248],[352,281],[510,320]].map(([x,y],i)=>tree(x,y,i)).join('')}
<g transform="translate(174 320)"><path d="M-25 0L0-14 28 2V33L1 48-25 33Z" fill="#e5d8a6"/><path d="M1 16L28 2V33L1 48Z" fill="#c6bb8a"/><path d="M-34 1L-4-34 33 0 1 19Z" fill="#e58a63"/><path d="M1 19L33 0-4-34 10-10Z" fill="#bd6550"/><path d="M-14 25l9 5v12l-9-5Z" fill="#426452"/></g>
<path class="home-field-border" d="M107 310L349 172 595 310 352 449Z" fill="none" stroke="#e5ffae" stroke-width="2" stroke-dasharray="8 8"/><g fill="#eaffb7" stroke="#315f41" stroke-width="2"><circle cx="107" cy="310" r="6"/><circle cx="349" cy="172" r="6"/><circle cx="595" cy="310" r="6"/><circle cx="352" cy="449" r="6"/></g><g class="home-roots" fill="none" stroke="#e9dcaa" stroke-width="2"><path d="M350 470v35m0-22-32-18m32 27 35-17M181 391v27m0-15-20-8M493 427v34m0-20 24-14"/></g></g><g class="home-sun"><circle cx="551" cy="108" r="58" fill="#ffca70" opacity=".08"/><circle cx="551" cy="108" r="42" fill="#ffca70" opacity=".14"/><circle cx="551" cy="108" r="27" fill="#ffce80"/></g><g class="home-cloud" fill="#c9e4cb"><path d="M92 160c-17-6-12-24 3-25 3-20 32-24 41-7 22-5 35 24 15 31Z" opacity=".6"/><path d="M437 100c-12-3-11-17 2-21 5-16 26-13 30 0 17-1 20 18 4 21Z" opacity=".25"/></g><g class="home-satellite" transform="translate(307 73) rotate(-20)"><path d="M0 0L14-8 27 0 14 8Z" fill="#eff6d6"/><path d="M14 8v17L0 17V0M14 25l13-8V0" fill="#9fb6a6"/><path d="M-5 3L-37-15-47 3-15 21ZM32 7L63 24 54 42 24 24Z" fill="#66afa9" stroke="#b6e2ce"/><path d="M-31-10l-10 18m22-11-10 18M43 14l-9 18m20-12-9 17" stroke="#b6e2ce"/><path d="M15 27Q14 47 35 44" fill="none" stroke="#e5edcd" stroke-width="2"/></g><path class="home-signal" d="M324 112L301 143M337 115L337 155M350 112L374 143" stroke="#bce99a" stroke-width="2" stroke-linecap="round"/></svg>`;}

export function mountLanding(host,{onBegin,onExplore}){
  host.innerHTML=`<div class="home-world" data-layer="water"><div class="home-grain" aria-hidden="true"></div><nav class="home-nav" aria-label="Inicio NORTEX"><a class="home-brand" href="#">◈ NORTEX<small>TAMBO · INTELIGENCIA AGRÍCOLA</small></a><span class="home-location"><i></i> VALLE DE SAN LORENZO · PIURA</span><button class="home-nav-cta" data-start>Encontrar mi finca ↗</button></nav><div class="home-hero"><div class="home-copy"><span class="home-kicker"><i></i> CONECTA CON EL ORIGEN</span><h1>Tu tierra<br>está <em>viva.</em><span>Decide qué cultivar.</span></h1><p>Decide qué cultivar con más información. Ubica tu finca y compara opciones de siembra, rotación y adaptación según el agua y el tiempo disponibles.</p><div class="home-actions"><button class="home-primary" data-start>Empezar con mi finca <span>↗</span></button><button class="home-secondary" id="homeExplore">Explorar qué cultivar <span>→</span></button></div><div class="home-assurance"><span>01</span> Ubica <b>—</b> <span>02</span> Delimita <b>—</b> <span>03</span> Compara cultivos</div></div><div class="home-playground"><div class="home-orbit" aria-hidden="true"></div><div class="home-art">${landscape()}</div><div class="home-coordinate" aria-hidden="true">TU PRÓXIMA DECISIÓN<br><strong>COMIENZA AQUÍ ↘</strong></div><div class="home-floating-label" aria-hidden="true"><span>◈</span> Una finca. Muchas señales.</div><div class="home-layer-picker" role="group" aria-label="Explorar señales del campo">${Object.entries(layers).map(([key,l],i)=>`<button data-layer="${key}" aria-pressed="${i===0}"><span>${l.symbol}</span> ${key==='water'?'Agua':key==='climate'?'Clima':'Suelo'}</button>`).join('')}</div><p class="home-art-caption">TOCA UNA SEÑAL Y EXPLORA · ILUSTRACIÓN INTERACTIVA</p></div></div><section class="home-discovery" aria-label="Lo que puedes explorar"><div class="home-discovery-symbol" aria-hidden="true">≈</div><div class="home-discovery-copy" aria-live="polite" aria-atomic="true"><span class="home-kicker" id="homeLayerLabel"></span><h2 id="homeLayerTitle"></h2><p id="homeLayerText"></p></div><button class="home-layer-action" id="homeLayerAction"></button></section><div class="home-bottom"><span>TECNOLOGÍA QUE EMPIEZA POR TU TERRITORIO.</span><p>Piloto experimental · Límite territorial provisional · Histórico climático 2025</p></div></div>`;
  const root=host.querySelector('.home-world');let active='water';
  host.querySelectorAll('[data-start]').forEach(b=>b.onclick=onBegin);
  host.querySelector('#homeExplore').onclick=()=>onExplore('plan');
  host.querySelector('#homeLayerAction').onclick=()=>onExplore(active==='soil'?'suelo':active==='climate'?'clima':'ia');
  function select(key){active=key;root.dataset.layer=key;const data=layers[key];host.querySelector('#homeLayerLabel').textContent=data.label;host.querySelector('#homeLayerTitle').textContent=data.title;host.querySelector('#homeLayerText').textContent=data.text;host.querySelector('#homeLayerAction').textContent=data.tag+' ↗';host.querySelector('.home-discovery-symbol').textContent=data.symbol;host.querySelectorAll('.home-layer-picker button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===key)));}
  host.querySelectorAll('.home-layer-picker button').forEach(b=>b.onclick=()=>select(b.dataset.layer));select(active);
  const stage=host.querySelector('.home-playground');
  stage.onpointermove=e=>{if(e.pointerType!=='mouse'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=stage.getBoundingClientRect();root.style.setProperty('--home-x',((e.clientX-r.left)/r.width-.5)*12+'px');root.style.setProperty('--home-y',((e.clientY-r.top)/r.height-.5)*10+'px');};
  stage.onpointerleave=()=>{root.style.setProperty('--home-x','0px');root.style.setProperty('--home-y','0px');};
}
